-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ptBR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.priest.dps.Name"] = "Dano"
L["rm.era.priest.dps.Description"] = "Dano do nível 1 ao 60, e o padrão do Sacerdote sempre que a rotação integrada de cura não se aplica (solo, Sombra ou ainda sem talentos). Forma de Sombra depois de aprendida; antes de puxar, um escudo quando solo, depois Fogo Sagrado (sem Forma de Sombra), Impacto Mental ou Punição. Palavra Sombria: Dor uma vez por alvo que vá sobreviver, Impacto Mental assim que sair do tempo de recarga, Açoite Mental como preenchimento (Punição e Nova Sagrada antes de tê-lo), e a varinha em um alvo morrendo ou quando sua mana fica baixa jogando solo. Abraço Vampírico e Peste Devoradora em lutas longas, nunca em raides. Lembretes: Fogo Interior, Fortitude, bônus raciais, Concentração Interior com Impacto Mental, Grito Psíquico quando dois inimigos chegam até você com metade da vida, Desvanecer quando seu alvo se volta contra você, Prece Desesperada. A escolha de alvo, vários DoTs e o uso de graus inferiores ficam com você."
L["rm.era.priest.dps.simulator.Name"] = "Dano (raide de Morto-vivo do simulador)"
L["rm.era.priest.dps.simulator.Description"] = "A prioridade de dano recomendada com a escolha de raide do simulador para sacerdotes Mortos-vivos: Concentração Interior é gasta em Peste Devoradora em vez de Impacto Mental, e Peste Devoradora é lançada também em raides, então use-a só onde sua raide tiver espaços de penalidade sobrando. Sem Abraço Vampírico. Uma alternativa à rotação integrada de dano recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
L["rm.era.priest.dps.warcrafttavern.Name"] = "Dano (economia de varinha da Warcraft Tavern)"
L["rm.era.priest.dps.warcrafttavern.Description"] = "O estilo de evolução de nível com pouco tempo parado da Warcraft Tavern, uma alternativa à rotação integrada de dano recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Solo: Impacto Mental para puxar, Palavra Sombria: Dor uma vez, Impacto Mental de novo só enquanto o alvo estiver acima de 30%, e sua varinha entre os Impactos Mentais em vez de Punição ou Açoite Mental. Nenhum escudo automático antes das puxadas. Em grupo: Palavra Sombria: Dor, Impacto Mental, Açoite Mental. Os mesmos lembretes da rotação integrada recomendada."
L["rm.era.priest.healer.Name"] = "Curador"
L["rm.era.priest.healer.Description"] = "Escolhida em grupo quando Sagrado ou Disciplina é sua árvore de talentos principal. Cura a unidade amigável que você selecionar: Palavra de Poder: Escudo abaixo de 30%, Cura Célere abaixo de 40%, dissipações, Prece de Cura quando três membros do seu grupo estiverem feridos, Cura Maior (Cura ou Cura Inferior antes de aprendê-la) abaixo de metade da vida, Renovar em movimento ou com dano leve, depois Cura grau 3 como complemento eficiente. Fora de combate, oferece Fortitude no seu alvo. Selecionar um inimigo dá Palavra Sombria: Dor e Punição. Lembretes: Fogo Interior, Fortitude, Espírito Divino, Concentração Interior, Prece Desesperada; Infusão de Poder vem desativada por padrão. A escolha de quem curar e o uso de graus inferiores ficam com você."
L["rm.forever.priest.dps.Name"] = "Sombra e dano solo"
L["rm.forever.priest.dps.Description"] = "Sombra, e o jogo solo de todo Sacerdote, do nível 1 ao 60; o padrão do Sacerdote no Forever. Puxa com Palavra de Poder: Escudo (solo) e Impacto Mental (Fogo Sagrado para Sagrado e Disciplina, Punição antes de Impacto Mental). Depois Forma de Sombra depois de aprendida, sua própria Palavra Sombria: Dor e Peste Devoradora, Impacto Mental, Fogo Sagrado seguido de Penitência para Disciplina, Açoite Mental em Forma de Sombra; solo antes de Forma de Sombra, Nova Sagrada contra três inimigos com Propósito Sagrado, depois a varinha (Punição sem uma). Em movimento: Dor, Peste. Lembretes: Fogo Interior, Fortitude, Espírito Divino, bônus raciais, Abraço Vampírico, Concentração Interior, Silêncio, Luz de Eluna; Grito Psíquico vem desativado por padrão. A vida e a mana ficam ocultas dos addons no Forever, então executar com Palavra Sombria: Morte, se curar e Sacrifício Sombrio são decisões suas. Montada a partir de guias do beta de nível 30; o jogo em Forma de Sombra segue a Mobalytics."
L["rm.forever.priest.dps.mobalytics.Name"] = "Evolução de nível com DoTs e varinha (Mobalytics)"
L["rm.forever.priest.dps.mobalytics.Description"] = "O estilo de evolução de nível da Mobalytics, uma alternativa à rotação integrada de Sombra recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Impacto Mental e Fogo Sagrado só em monstros difíceis (elites, ou dois níveis acima de você), sua própria Palavra Sombria: Dor e Peste Devoradora, depois a varinha (Punição sem uma). A partir de Forma de Sombra: Impacto Mental, Dor, Peste, Açoite Mental. Escudo e Renovar em você mesmo entre as puxadas, Curar Doença em você mesmo. A vida e a mana ficam ocultas dos addons no Forever, então se curar é decisão sua. Espalhar a Dor Irradiada por vários monstros fica com você."
L["rm.forever.priest.healer.Name"] = "Cura de Disciplina e Sagrado"
L["rm.forever.priest.healer.Description"] = "Cura em grupo assim que Disciplina ou Sagrado é sua árvore de talentos principal e você não conhece Forma de Sombra. Cura seu alvo amigável atual: antes da puxada, Palavra de Poder: Escudo, Prece da Recomposição e Renovar; Dissipar Magia e Abolir Doença ou Curar Doença; Prece da Recomposição; Nova Sagrada com Propósito Sagrado; Penitência; Renovar quando ausente; Cura (Cura Inferior antes dela). Em um inimigo: Palavra Sombria: Dor, Fogo Sagrado, Penitência, Punição, varinha. Lembretes: Fogo Interior, Fortitude, Espírito Divino, Infusão de Poder em outro jogador, Concentração Interior em combate e os feitiços raciais. A vida e a mana ficam ocultas dos addons no Forever, então o alvo que você escolhe é o único sinal de quem precisa de cura; curas de emergência, Prece de Cura, Cura Vinculada, Cura Maior e Cura Célere, Prece Desesperada e Sacrifício Sombrio são decisões suas. Você escolhe quem curar e o grau; um curador de Disciplina antes de Penitência (20–29) a seleciona manualmente."
L["rm.mop.priest.discipline.Name"] = "Recomendada"
L["rm.mop.priest.discipline.Description"] = "Cura de Disciplina do nível 10 ao 90, escolhida na especialização Disciplina. Selecione um aliado para curá-lo: Palavra de Poder: Escudo quando ele estiver com pouca vida, antes da puxada e mais ou menos a cada 12 segundos para Enlevo; Cura Célere com Torrente de Luz; Penitência; Cura Célere quando ele estiver com muito pouca vida; Cura Vinculada quando vocês dois estiverem feridos; Prece da Recomposição; Prece de Cura e seu talento do sexto nível quando três aliados estiverem feridos; Cura Maior; Renovar em movimento; Cura para completar. Sob Couraça Espiritual, sugere Prece de Cura ou Cura Maior. Selecione um inimigo para curar por meio de Reconciliação: Penitência, Palavra de Poder: Consolo ou Fogo Sagrado, seu talento do sexto nível em grupos de inimigos, Palavra Sombria: Dor quando solo, Punição. Lembretes: Fogo Interior, Fortitude, Arcanjo com cinco Evangelismo, Concentração Interior, Supressão de Dor em um alvo morrendo, Demônio das Sombras ou Dobramentes para mana, Infusão de Poder, Prece Desesperada. Fica com você: quem curar, o momento de Couraça Espiritual (um lembrete que você pode ativar), Palavra de Poder: Barreira, Deslocamento Caótico e os acúmulos de Graça no tanque."
L["rm.mop.priest.holy.Name"] = "Recomendada"
L["rm.mop.priest.holy.Description"] = "Cura de Sagrado do nível 10 ao 90, escolhida na especialização Sagrado. Selecione um aliado para curá-lo: Palavra Sagrada: Serenidade em Chacra: Serenidade; Palavra de Poder: Escudo só quando ele estiver prestes a morrer; Cura Célere com Torrente de Luz; Prece da Recomposição; Cura Célere com muito pouca vida; Cura Vinculada quando vocês dois estiverem feridos; em grupo com três aliados feridos, Círculo de Cura, Palavra Sagrada: Santuário em Chacra: Santuário, seu talento do sexto nível e Prece de Cura; Renovar; Cura Maior com pouca vida ou com dois Serendipidade; Cura. Selecione um inimigo para causar dano: Palavra Sagrada: Castigar, Palavra de Poder: Consolo ou Fogo Sagrado, Palavra Sombria: Dor quando solo, seu talento do sexto nível em grupos de inimigos, Punição. Um chacra vazio é preenchido para você (Santuário em raide, Serenidade em grupo, Castigar solo) e nunca trocado. Lembretes: Fogo Interior, Fortitude, Espírito Guardião em um alvo morrendo, Hino Divino quando cinco aliados estiverem muito feridos, Demônio das Sombras ou Dobramentes para mana, Infusão de Poder, Prece Desesperada. Fica com você: quem curar, posicionar Palavra Sagrada: Santuário, Fonte de Luz e Deslocamento Caótico."
L["rm.mop.priest.holy.icyveins.Name"] = "Curas de emergência por último (Icy Veins)"
L["rm.mop.priest.holy.icyveins.Description"] = "Desativada por padrão. A ordem de Sagrado da Icy Veins, escolhida pelo seu chacra. Em Chacra: Santuário: Palavra Sagrada: Santuário quando três aliados estiverem feridos, Renovar, Círculo de Cura, Prece da Recomposição, Prece de Cura, depois Cura Vinculada e Cura Célere só em emergências. Nos demais casos: Renovar, Palavra Sagrada: Serenidade, Prece da Recomposição, Cura Maior, Cura, Cura Vinculada, Cura Célere, Palavra de Poder: Escudo por último, e Cura Célere como preenchimento antes de você aprender Cura. A mesma condição de troca, os mesmos lembretes e a mesma lista de dano da rotação integrada recomendada de Sagrado; ative esta e desative aquela para usá-la."
L["rm.mop.priest.shadow.Name"] = "Recomendada"
L["rm.mop.priest.shadow.Description"] = "Dano de Sombra do nível 10 ao 90, escolhida na especialização Sombra. Abre com Aguilhão Mental, Impacto Mental ou seus DoTs. Peste Devoradora com três Orbes Sombrios (quando Impacto Mental estiver pronto ou ainda a seis segundos), Impacto Mental, Palavra Sombria: Morte abaixo de 20% de vida, Açoite Mental enquanto sua Peste Devoradora estiver ativa se você pegou Consolação e Insanidade, Palavra Sombria: Dor e Toque Vampírico renovados perto do fim em um alvo que vá sobreviver, Aguilhão Mental com Torrente de Escuridão, Halo, Cascata ou Estrela Divina no melhor alcance, depois Açoite Mental. Um Açoite Mental é interrompido para Impacto Mental ou Palavra Sombria: Morte, ou depois do segundo pulso dele; outras canalizações nunca são interrompidas. Em movimento, sugere só instantâneos. Contra cinco ou mais inimigos: seu talento do sexto nível, DoTs no seu alvo e Calcinação Mental. Lembretes: Forma de Sombra, Fogo Interior, Fortitude, Silêncio em lançamentos interrompíveis, Demônio das Sombras ou Dobramentes e Infusão de Poder em lutas longas, Abraço Vampírico, Prece Desesperada e Dispersão com pouca vida. Fica com você: DoTs em outros alvos e onde Calcinação Mental cai."
L["rm.mop.priest.shadow.warcrafttavern.Name"] = "Sem prioridade de Insanidade (Warcraft Tavern)"
L["rm.mop.priest.shadow.warcrafttavern.Description"] = "Desativada por padrão. A ordem de Sombra da Warcraft Tavern: Peste Devoradora com três Orbes Sombrios, Palavra Sombria: Morte abaixo de 20%, Impacto Mental, Toque Vampírico, Palavra Sombria: Dor, Aguilhão Mental com Torrente de Escuridão, seu talento do sexto nível, Açoite Mental. Ao contrário da rotação integrada recomendada de Sombra, ela nunca sobe Açoite Mental sob Peste Devoradora e não segura Peste Devoradora para Impacto Mental. Os mesmos passos de abertura, movimento, grupos de inimigos e lembretes; ative esta e desative a recomendada para usá-la."
L["rm.mop.priest.unspecialized.Name"] = "Sem especialização"
L["rm.mop.priest.unspecialized.Description"] = "Para os níveis 1 a 9, ou qualquer sacerdote que ainda não escolheu uma especialização. Em um inimigo: Palavra Sombria: Dor quando ele for viver tempo suficiente, depois Punição. Em um aliado: Cura Célere quando ele estiver com pouca vida, senão Palavra de Poder: Escudo. Lembretes: Fogo Interior, e um escudo em você mesmo quando estiver solo e ferido. Escolher uma especialização no nível 10 troca para a rotação integrada dela."
L["rm.retail.priest.discipline.Name"] = "Expiação (Icy Veins)"
L["rm.retail.priest.discipline.Description"] = "Disciplina no Midnight, como referência: o Assistente de Combate da Blizzard não cobre curadores, o jogo oculta a vida de todos em combate e o Rotation Master escolhe um feitiço, não um alvo, então esta rotação executa o dano que cura por meio de Expiação e deixa com você a decisão de quem curar. Em um alvo amigável: Palavra de Poder: Escudo (Escudo Caótico), Penitência, Cura Célere. Em um inimigo: Palavra Sombria: Dor quando você não a lançou nos últimos 12 segundos, Impacto Mental, Penitência, Escudo, Palavra Sombria: Morte, Impacto do Caos, Punição. Lembretes em combate: Palavra de Poder: Resplendor, Evangelismo, Penitência Suprema, Supressão de Dor em um alvo amigável; Fortitude entre os combates. Prece Desesperada fica por sua conta. As rampas de cura da raide antes de dano pesado ficam a seu critério."
L["rm.retail.priest.discipline.wowhead.Name"] = "Referência de Morte primeiro (Wowhead)"
L["rm.retail.priest.discipline.wowhead.Description"] = "Apenas referência, desativada por padrão: a ordem Oráculo da Temporada 1 da Wowhead, que mantém Palavra Sombria: Dor ativa lendo a penalidade que o Midnight oculta em combate. Palavra Sombria: Dor, Palavra Sombria: Morte assim que sair do tempo de recarga, Penitência, Impacto Mental, Punição; Penitência primeiro em um alvo amigável. Os mesmos lembretes da rotação integrada da Icy Veins."
L["rm.retail.priest.holy.Name"] = "Icy Veins"
L["rm.retail.priest.holy.Description"] = "Sagrado no Midnight, como referência: o jogo oculta a vida de todos em combate e o Rotation Master escolhe um feitiço, não um alvo, então esta rotação mantém suas Palavras Sagradas, Prece da Recomposição e ativações girando em qualquer alvo que você selecionar e deixa a triagem com você. Em um alvo amigável: Palavra Sagrada: Santificar, Palavra Sagrada: Serenidade, Prece da Recomposição, Prece de Cura com Torrente de Luz, Bênção, Prece de Cura com Tecelume, Cura Célere com Torrente de Luz, Prece de Cura em grupo, Nova Sagrada em movimento, Cura Célere. Em um inimigo: Palavra Sagrada: Castigar, Fogo Sagrado, Nova Sagrada em movimento, Punição. Lembretes: Apoteose, Hino Divino e Halo em combate, Espírito Guardião em um alvo amigável (a vida fica oculta no Retail, então decidir se ele está prestes a morrer é com você), Fortitude. Prece Desesperada fica com você."
L["rm.retail.priest.initial.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.priest.initial.Description"] = "Recomendada antes de você escolher uma especialização (enquanto o jogo informa a especialização inicial do Sacerdote). Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, os lembretes que toda rotação integrada de Sacerdote compartilha, cada um assim que você conhece o feitiço dele. Quando você escolhe uma especialização no nível 10, as rotações integradas dessa especialização assumem."
L["rm.retail.priest.shadow.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.priest.shadow.Description"] = "Recomendada para Sombra no Midnight. Em combate, o jogo agora oculta seus DoTs, bônus, tempos de recarga e vida para addons, então esta rotação mostra a própria sugestão do Assistente de Combate da Blizzard (a rotação de um botão, que mantém seus DoTs, Forma de Sombra e Forma do Caos e deixa Açoite Mental terminar), e para enquanto você lança ou não tem um inimigo como alvo. Lembretes do que ela deixa de fora: Infusão de Poder nos 20 segundos depois de você lançar Forma do Caos, Forma de Sombra e Palavra de Poder: Fortitude entre os combates, Silêncio em um lançamento interrompível (só acende onde o jogo permite ler o lançamento). A vida fica oculta no Retail, então Prece Desesperada fica por sua conta."
L["rm.retail.priest.shadow.icyveins.Name"] = "Referência (Icy Veins)"
L["rm.retail.priest.shadow.icyveins.Description"] = "Apenas referência, desativada por padrão: a ordem da Icy Veins e do SimulationCraft lê os temporizadores dos DoTs, Loucura e Forma do Caos, que o Midnight oculta em combate; a Insanidade e a vida ficam ocultas no Retail, então a Loucura no limite de Insanidade, a execução com Palavra Sombria: Morte e Prece Desesperada ficam com você. Toque Vampírico antes da puxada; Batida com Tentáculo para aplicar Toque Vampírico; Toque Vampírico e Palavra Sombria: Dor renovados nos últimos 30%; Palavra Sombria: Loucura quando estiver acabando ou durante Forma do Caos; Impacto do Caos durante Loucura; Batida com Tentáculo com duas cargas; Torrente do Caos; Impacto Mental; Batida com Tentáculo; Açoite Mental: Insanidade durante Loucura; Salva do Caos; Morte e Dor em movimento; Açoite Mental, interrompido para um Impacto Mental pronto. Lembretes: Halo, Forma do Caos com os dois DoTs ativos, Infusão de Poder durante Forma do Caos."
L["rm.sod.priest.dps.Name"] = "Dano (SoD)"
L["rm.sod.priest.dps.Description"] = "Dano em reinos da Temporada da Descoberta, do nível 1 ao 60, usando as runas que você gravou. Forma de Sombra; Toque Vampírico ou Impacto Mental para puxar (Penitência, Fogo Sagrado ou Punição antes da Forma de Sombra). Peste do Caos, Palavra Sombria: Dor e Toque Vampírico mantidos (renovados perto do fim só sem Dor e Sofrimento gravado), Impacto Mental assim que sair do tempo de recarga, Açoite Mental com Faces Desfeitas, Palavra Sombria: Morte enquanto você estiver acima de metade da vida, depois Aguilhão Mental como preenchimento, ou Açoite Mental com o conjunto de seis peças da Fase 8. Área de Caos e Calcinação Mental contra quatro ou mais inimigos. A varinha em um alvo morrendo quando solo. Lembretes: Fogo Interior, Fortitude, Homúnculos, Demônio das Sombras, Olho do Caos e Dispersão, Concentração Interior, Grito Psíquico, Desvanecer, Prece Desesperada."
L["rm.sod.priest.dps.wowhead.Name"] = "Dano (SoD, acúmulos de Aguilhão Mental da Wowhead)"
L["rm.sod.priest.dps.wowhead.Description"] = "O método da Wowhead e da Warcraft Tavern para a Temporada da Descoberta, uma alternativa à rotação integrada de dano da Temporada da Descoberta recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Impacto Mental espera três dos seus acúmulos de Aguilhão Mental no alvo (é lançado normalmente até você gravar Aguilhão Mental), Açoite Mental só com Faces Desfeitas, Aguilhão Mental como preenchimento. Todo o resto é igual à rotação integrada recomendada."
L["rm.sod.priest.healer.Name"] = "Curador (SoD)"
L["rm.sod.priest.healer.Description"] = "Escolhida em reinos da Temporada da Descoberta, em grupo, quando Sagrado ou Disciplina é sua árvore de talentos principal; segue a Icy Veins. Cura a unidade amigável que você selecionar: Prece da Recomposição antes da puxada e sempre que estiver pronta, Escudo abaixo de metade da vida, Penitência, Cura Célere instantânea com Torrente de Luz, Cura Célere de emergência, dissipações, Círculo de Cura e Prece de Cura quando três membros do seu grupo estiverem feridos, Cura Maior abaixo de metade da vida, Renovar em movimento ou com dano leve, depois Cura. Selecionar um inimigo dá Dor, Peste do Caos, Penitência, Fogo Sagrado e Punição. Os lembretes incluem Demônio das Sombras, Supressão de Dor em um alvo morrendo, Palavra de Poder: Barreira e Espírito do Redentor quando o grupo estiver ferido."
L["rm.sod.priest.healer.warcrafttavern.Name"] = "Curador (SoD, Warcraft Tavern)"
L["rm.sod.priest.healer.warcrafttavern.Description"] = "O ciclo de Serendipidade da Warcraft Tavern, feito para Serendipidade e Proteção Anímica, uma alternativa à rotação integrada de curandeiro da Temporada da Descoberta recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Prece da Recomposição assim que sair do tempo de recarga, Escudo no seu alvo sempre que ele puder receber um (com Proteção Anímica gravada; senão abaixo de metade da vida), Penitência com dano pesado, Círculo de Cura para três feridos, Cura Maior ou Prece de Cura com três acúmulos de Serendipidade, Renovar com dano menor, e Cura Célere em ferimentos leves para acumular (com Serendipidade gravada; senão abaixo de 30%)."
L["rm.tbc.priest.dps.icyveins.Name"] = "Dano (Icy Veins)"
L["rm.tbc.priest.dps.icyveins.Description"] = "Dano do nível 1 ao 70, usada sempre que a rotação integrada de cura não se aplica. Punição e varinha no início, depois Impacto Mental, Palavra Sombria: Dor, Açoite Mental, Forma de Sombra, Toque Vampírico e Palavra Sombria: Morte conforme você os aprende; DoTs antes de Impacto Mental; quando solo, um alvo morrendo é finalizado com a varinha. Quem faz missões como Sagrado ou Disciplina recebe Fogo Sagrado e Punição. Lembretes: Fogo Interior, Fortitude, bônus raciais, Concentração Interior, Demônio das Sombras. Um Açoite Mental além do primeiro pulso é interrompido para um Impacto Mental pronto, ou para Palavra Sombria: Morte com mais da metade da vida. Escudos e cura ficam com você."
L["rm.tbc.priest.dps.wowhead.Name"] = "Dano (Wowhead)"
L["rm.tbc.priest.dps.wowhead.Description"] = "Dano segundo os guias da Wowhead, uma alternativa à rotação integrada de dano da Icy Veins recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Impacto Mental abre e vem antes da renovação dos DoTs, Abraço Vampírico só quando sua vida cai, e um alvo morrendo recebe feitiços em vez da varinha. No resto, igual à rotação integrada recomendada."
L["rm.tbc.priest.healer.icyveins.Name"] = "Curador (Icy Veins)"
L["rm.tbc.priest.healer.icyveins.Description"] = "Cura na ordem da Icy Veins: Escudo, dissipações, Cura Vinculada, Renovar, Cura Célere, Cura Maior (qualquer grau), curas em grupo e Prece da Recomposição por último. Você escolhe quem curar. Uma alternativa à rotação integrada de curandeiro da Wowhead recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
L["rm.tbc.priest.healer.wowhead.Name"] = "Curador (Wowhead)"
L["rm.tbc.priest.healer.wowhead.Description"] = "Cura em grupo quando Sagrado ou Disciplina é sua árvore de talentos principal. Dá sugestões para a unidade amigável que você tem como alvo; você escolhe quem curar. Prece da Recomposição antes de puxar e sempre que estiver pronta, Renovar, Palavra de Poder: Escudo em emergências, dissipações, Círculo de Cura ou Prece de Cura para dano em grupo, Cura Vinculada, Cura Célere e Cura Maior, e Cura Maior de grau 1 como complemento barato. Com um inimigo como alvo, oferece um pouco de dano."
